import itertools
vis = (a!=8)
def score(fi, fj):
    bad=tot=0
    for i in range(30):
        for j in range(30):
            if not vis[i,j]: continue
            i2,j2=fi(i),fj(j)
            if i2==i and j2==j: continue
            if 0<=i2<30 and 0<=j2<30 and vis[i2,j2]:
                tot+=1
                if a[i,j]!=a[i2,j2]: bad+=1
    return bad,tot
fns={'id':lambda x:x,'r15':lambda x:15-x,'r31':lambda x:31-x}
res=[]
for fn,fq in itertools.product(fns.items(),fns.items()):
    if (fn[1],fq[1])==('id','id'): continue
    b,t=score(fn[1],fq[1])
    res.append((b,t,fn[0],fq[0]))
res.sort()
for r in res: print(r)
